/**
 * Motifs for catalog modules in R04 Historia & kultur (0.28). Same geometry format as motifs.ts.
 */
import type { Motif, Part, Role } from './motifs';

const p = (d: string, r: Role, hue?: number): Part => ({ t: 'path', d, r, hue });
const c = (cx: number, cy: number, rad: number, r: Role, hue?: number): Part => ({ t: 'circle', cx, cy, rad, r, hue });
const q = (x: number, y: number, w: number, h: number, r: Role, rx = 1.5, hue?: number): Part => ({ t: 'rect', x, y, w, h, rx, r, hue });
const G = { green: 115, orange: 26, red: 6, yellow: 46, blue: 210, grey: 220, purple: 285, brown: 28, sand: 40 } as const;
const fig = (x: number, y: number, s: number, r: Role): Part[] => [c(x, y - 14 * s, 5 * s, r), p(`M${x - 7 * s} ${y + 12 * s} V${y - 2 * s} C${x - 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 2 * s} V${y + 12 * s} Z`, r)];
const star = (x: number, y: number, r: number, role: Role, hue?: number): Part => { const pts = Array.from({ length: 10 }, (_, i) => { const a = -Math.PI / 2 + (i * Math.PI) / 5; const rr = i % 2 ? r * 0.45 : r; return `${(x + Math.cos(a) * rr).toFixed(1)} ${(y + Math.sin(a) * rr).toFixed(1)}`; }); return p(`M${pts.join(' L')} Z`, role, hue); };
const bubble = (x: number, y: number, w: number, h: number, r: Role): Part => p(`M${x + 4} ${y} H${x + w - 4} Q${x + w} ${y} ${x + w} ${y + 4} V${y + h - 4} Q${x + w} ${y + h} ${x + w - 4} ${y + h} H${x + 14} L${x + 6} ${y + h + 7} V${y + h} H${x + 4} Q${x} ${y + h} ${x} ${y + h - 4} V${y + 4} Q${x} ${y} ${x + 4} ${y} Z`, r);
const doc = (x: number, y: number, w: number, h: number, lines = 3): Part[] => [q(x, y, w, h, 'light', 2), p(Array.from({ length: lines }, (_, i) => `M${x + 5} ${y + 8 + i * 7} H${x + w - (i === lines - 1 ? 12 : 5)}`).join(' '), 'line')];
const scroll = (x: number, y: number, w: number, h: number, r: Role = 'light'): Part[] => [q(x, y + 3, w, h - 6, r, 0), q(x - 3, y, w + 6, 5, 'accent', 2.5), q(x - 3, y + h - 5, w + 6, 5, 'accent', 2.5), p(`M${x + 4} ${y + 12} H${x + w - 4} M${x + 4} ${y + 18} H${x + w - 4} M${x + 4} ${y + 24} H${x + w - 8}`, 'line')];
const temple = (x: number, y: number, w: number, h: number, r: Role = 'main'): Part[] => [p(`M${x} ${y + 9} L${x + w / 2} ${y} L${x + w} ${y + 9} Z`, r), q(x, y + h - 5, w, 5, r, 1), ...[0, 1, 2, 3].map((i) => q(x + 3 + i * ((w - 10) / 3), y + 11, 4, h - 16, 'light', 1))];
const castle = (x: number, y: number, w: number, h: number, r: Role = 'main'): Part[] => [p(`M${x} ${y + h} V${y} H${x + 6} V${y + 5} H${x + 12} V${y} H${x + w - 12} V${y + 5} H${x + w - 6} V${y} H${x + w} V${y + h} Z`, r), p(`M${x + w / 2 - 6} ${y + h} V${y + h - 12} A6 6 0 0 1 ${x + w / 2 + 6} ${y + h - 12} V${y + h} Z`, 'light')];
const tower = (x: number, y: number, w: number, h: number, r: Role): Part => p(`M${x} ${y + h} V${y} H${x + w / 4} V${y + 4} H${x + w / 2 - 1} V${y} H${x + w / 2 + 1} V${y + 4} H${x + (3 * w) / 4} V${y} H${x + w} V${y + h} Z`, r);
const sword = (x: number, y: number, len: number, r: Role = 'light'): Part[] => [p(`M${x} ${y} L${x + 3} ${y + 4} V${y + len} H${x - 3} V${y + 4} Z`, r), q(x - 8, y + len, 16, 3, 'accent', 1), q(x - 1.5, y + len + 3, 3, 8, 'main', 1)];
const shield = (x: number, y: number, s: number, r: Role, hue?: number): Part => p(`M${x} ${y} L${x + 14 * s} ${y + 5 * s} V${y + 16 * s} C${x + 14 * s} ${y + 26 * s} ${x + 6 * s} ${y + 32 * s} ${x} ${y + 34 * s} C${x - 6 * s} ${y + 32 * s} ${x - 14 * s} ${y + 26 * s} ${x - 14 * s} ${y + 16 * s} V${y + 5 * s} Z`, r, hue);
const spear = (x: number, y1: number, y2: number): Part[] => [p(`M${x} ${y1 + 6} V${y2}`, 'line'), p(`M${x} ${y1} L${x + 3} ${y1 + 7} H${x - 3} Z`, 'light')];
const crown = (x: number, y: number, w: number, r: Role = 'accent'): Part => p(`M${x} ${y + 12} L${x - 2} ${y} L${x + w * 0.25} ${y + 6} L${x + w / 2} ${y - 2} L${x + w * 0.75} ${y + 6} L${x + w + 2} ${y} L${x + w} ${y + 12} Z`, r, G.yellow);
const book = (x: number, y: number, w: number, h: number, r: Role = 'main'): Part[] => [p(`M${x} ${y + 3} C${x + w * 0.2} ${y} ${x + w * 0.4} ${y} ${x + w / 2} ${y + 4} C${x + w * 0.6} ${y} ${x + w * 0.8} ${y} ${x + w} ${y + 3} V${y + h} C${x + w * 0.8} ${y + h - 3} ${x + w * 0.6} ${y + h - 3} ${x + w / 2} ${y + h + 1} C${x + w * 0.4} ${y + h - 3} ${x + w * 0.2} ${y + h - 3} ${x} ${y + h} Z`, r), p(`M${x + w / 2} ${y + 4} V${y + h + 1}`, 'line'), p(`M${x + 4} ${y + 10} H${x + w / 2 - 4} M${x + 4} ${y + 16} H${x + w / 2 - 4} M${x + w / 2 + 4} ${y + 10} H${x + w - 4} M${x + w / 2 + 4} ${y + 16} H${x + w - 4}`, 'line')];
const pot = (x: number, y: number, s: number, r: Role, hue?: number): Part => p(`M${x - 6 * s} ${y} H${x + 6 * s} L${x + 4 * s} ${y + 4 * s} C${x + 12 * s} ${y + 8 * s} ${x + 12 * s} ${y + 22 * s} ${x + 4 * s} ${y + 26 * s} H${x - 4 * s} C${x - 12 * s} ${y + 22 * s} ${x - 12 * s} ${y + 8 * s} ${x - 4 * s} ${y + 4 * s} Z`, r, hue);
const ship = (x: number, y: number, s: number, r: Role): Part[] => [p(`M${x - 22 * s} ${y} H${x + 22 * s} C${x + 18 * s} ${y + 8 * s} ${x - 18 * s} ${y + 8 * s} ${x - 22 * s} ${y} Z`, r), p(`M${x} ${y} V${y - 26 * s}`, 'line'), p(`M${x + 1} ${y - 24 * s} H${x + 16 * s} V${y - 6 * s} H${x + 1} Z`, 'light')];
const globe = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'main', G.blue), p(`M${x - r * 0.6} ${y - r * 0.3} C${x - r * 0.2} ${y - r * 0.6} ${x} ${y} ${x + r * 0.3} ${y - r * 0.2} C${x + r * 0.6} ${y - r * 0.4} ${x + r * 0.7} ${y + r * 0.2} ${x + r * 0.3} ${y + r * 0.4} C${x} ${y + r * 0.5} ${x - r * 0.4} ${y + r * 0.3} ${x - r * 0.6} ${y - r * 0.3} Z`, 'accent', G.green)];
const brain = (r: Role = 'main'): Part => p('M14 24 C10 16 16 8 26 10 C30 4 40 6 42 12 C52 12 56 22 50 28 C52 36 42 40 36 36 C30 40 18 38 18 32 C12 32 10 26 14 24 Z', r);
const scales0 = (x: number, y: number): Part[] => [p(`M${x} ${y - 18} V${y + 18} M${x - 9} ${y + 18} H${x + 9} M${x - 18} ${y - 12} H${x + 18}`, 'line'), p(`M${x - 24} ${y + 2} Q${x - 18} ${y + 9} ${x - 12} ${y + 2} Z`, 'main'), p(`M${x + 12} ${y + 2} Q${x + 18} ${y + 9} ${x + 24} ${y + 2} Z`, 'accent'), p(`M${x - 18} ${y - 12} L${x - 24} ${y + 2} M${x - 18} ${y - 12} L${x - 12} ${y + 2} M${x + 18} ${y - 12} L${x + 12} ${y + 2} M${x + 18} ${y - 12} L${x + 24} ${y + 2}`, 'line')];
const arrowR = (x1: number, x2: number, y: number): Part => p(`M${x1} ${y} H${x2} M${x2 - 4} ${y - 4} L${x2} ${y} L${x2 - 4} ${y + 4}`, 'line');
const check = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} L${x - 1 * s} ${y + 4 * s} L${x + 6 * s} ${y - 4 * s}`, 'line');
const hourglass = (x: number, y: number, r: Role = 'light'): Part[] => [q(x - 12, y, 24, 4, 'main', 2), q(x - 12, y + 36, 24, 4, 'main', 2), p(`M${x - 9} ${y + 4} H${x + 9} C${x + 9} ${y + 13} ${x + 2} ${y + 16} ${x + 2} ${y + 20} C${x + 2} ${y + 24} ${x + 9} ${y + 27} ${x + 9} ${y + 36} H${x - 9} C${x - 9} ${y + 27} ${x - 2} ${y + 24} ${x - 2} ${y + 20} C${x - 2} ${y + 16} ${x - 9} ${y + 13} ${x - 9} ${y + 4} Z`, r), p(`M${x - 6} ${y + 34} C${x - 4} ${y + 30} ${x + 4} ${y + 30} ${x + 6} ${y + 34} Z`, 'accent')];
const pyramid = (x: number, y: number, w: number, r: Role, hue?: number): Part[] => [p(`M${x} ${y + w * 0.6} L${x + w / 2} ${y} L${x + w} ${y + w * 0.6} Z`, r, hue), p(`M${x + w / 2} ${y} L${x + w * 0.62} ${y + w * 0.6} H${x + w} Z`, 'accent2', hue)];

